import hashlib,json,tarfile
from pathlib import Path
from datetime import datetime,timezone
root=Path(CONFIG['root']).resolve()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
for r in CONFIG['old_helpers']:
    assert sha(Path(r['remote_path']))==r['sha256'],r['remote_path']
assert sha(Path(CONFIG['bundle']))==CONFIG['bundle_sha']
expected={str(Path(r['remote_path']).relative_to(root)):r for r in CONFIG['members']}
with tarfile.open(CONFIG['bundle'],'r:gz') as archive:
    entries=archive.getmembers();assert len(entries)==len(expected)
    for item in entries:
        assert item.isfile() and item.name in expected,item.name
        target=(root/item.name).resolve();assert target.is_relative_to(root)
        r=expected[item.name];raw=archive.extractfile(item).read()
        assert hashlib.sha256(raw).hexdigest()==r['sha256'] and len(raw)==r['size_bytes'],item.name
        if target.exists():assert sha(target)==r['sha256'],'existing different: '+item.name
    created=0;unchanged=0
    for item in entries:
        target=root/item.name
        if target.exists():unchanged+=1;continue
        target.parent.mkdir(parents=True,exist_ok=True)
        with target.open('xb') as f:f.write(archive.extractfile(item).read())
        created+=1
receipt={'status':'INPUTS_DEPLOYED_NO_CALL','utc':datetime.now(timezone.utc).isoformat(),'bundle_sha256':CONFIG['bundle_sha'],'new_files':created,'existing_identical_files':unchanged,'old_helpers_unchanged':True,'api_calls':0}
out=root/'PLAN/feedback_sys/P3NEW/results/native_author_current_r1/deployment_receipt.json';out.write_text(json.dumps(receipt,indent=2)+'\n',encoding='utf-8')
print(json.dumps(receipt))
